from typing import List, Tuple

def func(inputs: List[Tuple[int, int, int, List[Tuple[int, int, int, int]], int, List[Tuple[int, int, int]]]]) -> str:    
    N, M, r, ranges, q, queries = inputs[0]

    ranges_dict = {}
    for t, n, m, s in ranges:
        if m not in ranges_dict:
            ranges_dict[m] = []
        ranges_dict[m].append((t, s))

    for m in ranges_dict:
        ranges_dict[m].sort()

    result = []
    for ts, te, m in queries:
        if m in ranges_dict:
            i = 0
            is_found = False
            while i < len(ranges_dict[m]):
                t, s = ranges_dict[m][i]
                if ts <= t < te:
                    result.append(str(s))
                    is_found = True
                    break
                i += 1
            if not is_found:
                result.append('0')
        else:
            result.append('0')

    return ','.join(result)


if __name__ == "__main__":
    print(func([(4, 2, 10, 
     [(775, 1, 1, 1), (780, 4, 2, 1), (790, 2, 1, 1), (800, 2, 1, 0), (810, 3, 1, 1), (820, 1, 1, 0), (825, 3, 1, 0), (860, 1, 1, 1), (870, 4, 2, 0), (880, 1, 1, 0)], 
     1, 
     [(780, 870, 1)]]))

```

